package main

import (
	"bytes"
	"fmt"
	"image/jpeg"
)

func check(data []byte, expected []byte, w int, h int) bool {
	img, err := jpeg.Decode(bytes.NewReader(data))
	if err != nil {
		return false
	}
	b := img.Bounds()
	if b.Dx() != w || b.Dy() != h {
		return false
	}
	match := true
	y := 0
	for y < h {
		x := 0
		for x < w {
			off := img.PixOffset(x, y)
			eoff := (y*w + x) * 3
			if img.Pix[off] != expected[eoff] || img.Pix[off+1] != expected[eoff+1] || img.Pix[off+2] != expected[eoff+2] {
				match = false
			}
			x = x + 1
		}
		y = y + 1
	}
	return match
}

